package main.engine;


import java.util.ArrayList;
import java.util.List;

import main.domain.*;

public class MatchingEngine {
    private final OrderBook book;
    
    // In a real system, this would be a high-performance message queue (like Disruptor),
    // but for our core logic, we return a list of trades generated by the input.
    public MatchingEngine(OrderBook book) {
        this.book = book;
    }

    /**
     * Main entry point for the engine.
     */
    public List<Trade> process(Order aggressiveOrder, long logicalTimestamp) {
        List<Trade> executions = new ArrayList<>();
        // Invert control: tell the order to match itself against this engine
        aggressiveOrder.processBy(this, executions, logicalTimestamp);
        return executions;
    }

    // --- Double Dispatch Resolution ---

    /**
     * Matches an incoming aggressive BUY order against the resting ASKS (Sellers).
     */
    public void match(BuyOrder aggressiveBuy, List<Trade> executions, long timestamp) {
        // While the buyer still needs quantity and there are sellers available
        while (!aggressiveBuy.isFilled() && book.hasAsks()) {
            PriceLevel bestAskLevel = book.getBestAskLevel();

            // Price Priority: Buyer is not willing to pay the cheapest seller's price
            if (aggressiveBuy.getPrice() < bestAskLevel.getPrice()) {
                break; 
            }

            executeLevel(aggressiveBuy, bestAskLevel, executions, timestamp);
            
            // Clean up the book if the price level is depleted
            if (bestAskLevel.isEmpty()) {
                book.removeBestAsk();
            }
        }

        // If the aggressive order is not fully filled, enqueue the remainder
        if (!aggressiveBuy.isFilled()) {
            book.enqueueOrder(aggressiveBuy);
        }
    }

    /**
     * Matches an incoming aggressive SELL order against the resting BIDS (Buyers).
     */
    public void match(SellOrder aggressiveSell, List<Trade> executions, long timestamp) {
        while (!aggressiveSell.isFilled() && book.hasBids()) {
            PriceLevel bestBidLevel = book.getBestBidLevel();

            // Price Priority: Seller is not willing to sell at the highest buyer's price
            if (aggressiveSell.getPrice() > bestBidLevel.getPrice()) {
                break;
            }

            executeLevel(aggressiveSell, bestBidLevel, executions, timestamp);

            if (bestBidLevel.isEmpty()) {
                book.removeBestBid();
            }
        }

        if (!aggressiveSell.isFilled()) {
            book.enqueueOrder(aggressiveSell);
        }
    }

    /**
     * Time Priority: Executes the aggressive order against the oldest resting orders in a specific price level.
     */
    private void executeLevel(Order aggressiveOrder, PriceLevel restingLevel, List<Trade> executions, long timestamp) {
        OrderNode currentRestingNode = restingLevel.getHead();

        while (currentRestingNode != null && !aggressiveOrder.isFilled()) {
            Order restingOrder = currentRestingNode.getOrder();

            // Calculate the trade size (minimum between what is wanted and what is available)
            long tradeQuantity = Math.min(aggressiveOrder.getRemainingQuantity(), restingOrder.getRemainingQuantity());
            long tradePrice = restingLevel.getPrice(); // The trade always happens at the resting order's price

            // Encapsulated state mutation
            aggressiveOrder.fill(tradeQuantity);
            restingOrder.fill(tradeQuantity);

            // Generate immutable event
            executions.add(new Trade(
                aggressiveOrder.getId(), 
                restingOrder.getId(), 
                tradePrice, 
                tradeQuantity, 
                timestamp
            ));

            // If the resting order is fully consumed, remove it from the book
            OrderNode nextNode = currentRestingNode.getNext();
            if (restingOrder.isFilled()) {
                restingLevel.removeOrder(currentRestingNode);
                book.removeActiveOrder(restingOrder.getId()); // O(1) removal from the global map
            }
            
            currentRestingNode = nextNode;
        }
    }
}
